"""Original CC0-1.0 training examples for local Python maintenance."""
import json
from pathlib import Path

examples = [
    ("adapt_names", "Implement to_snake(name) for PascalCase or camelCase ASCII identifiers. Keep runs of capitals together, including before the final word. Lowercase the result. Examples: HTTPRequest -> http_request, buildID -> build_id.",
     'import re\n\ndef to_snake(name):\n    name = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\\1_\\2", name)\n    return re.sub(r"([a-z0-9])([A-Z])", r"\\1_\\2", name).lower()',
     'assert [to_snake(x) for x in ["HTTPRequest", "buildID", "Batch", "parseURLPath", ""]] == ["http_request", "build_id", "batch", "parse_url_path", ""]'),
    ("compare_versions", "Implement compare_version(a, b). Compare dotted nonnegative integer version components numerically, padding shorter versions with trailing zeros. Return -1, 0 or 1.",
     'from itertools import zip_longest\n\ndef compare_version(a, b):\n    components = zip_longest(map(int, a.split(".")), map(int, b.split(".")), fillvalue=0)\n    for left, right in components:\n        if left != right:\n            return (left > right) - (left < right)\n    return 0',
     'assert compare_version("2.10", "2.9") == 1\nassert compare_version("1", "1.0.0") == 0\nassert compare_version("1.1", "2") == -1'),
    ("prefix_routes", "Implement select_route(path, routes) given an absolute path and a mapping from absolute route prefixes to handler objects. Choose the longest matching prefix on a path-component boundary, with / as fallback. Return None if nothing matches.",
     'def select_route(path, routes):\n    matched = (prefix for prefix in routes if prefix == "/" or path == prefix or path.startswith(prefix + "/"))\n    prefix = max(matched, key=len, default=None)\n    return routes[prefix] if prefix is not None else None',
     'handlers = {"/": 1, "/projects": 2, "/projects/files": 3}\nassert select_route("/projects/files/1", handlers) == 3\nassert select_route("/projects2", handlers) == 1\nassert select_route("/none", {}) is None'),
    ("limit_bytes", "Implement utf8_prefix(text, budget), returning the longest prefix of text using at most budget UTF-8 bytes. Return an empty string for nonpositive budget. Keep whole characters.",
     'def utf8_prefix(text, budget):\n    if budget <= 0:\n        return ""\n    return text.encode("utf-8")[:budget].decode("utf-8", errors="ignore")',
     'assert utf8_prefix("a€Ω", 3) == "a"\nassert utf8_prefix("a€Ω", 4) == "a€"\nassert utf8_prefix("test", -1) == ""'),
    ("quantity", "Implement parse_quantity(text) accepting integers with an optional lowercase k suffix (multiply by 1000) or M suffix (multiply by 1000000). Strip surrounding whitespace, reject internal whitespace and invalid syntax with ValueError.",
     'import re\n\ndef parse_quantity(text):\n    found = re.fullmatch(r"([+-]?[0-9]+)([kM]?)", text.strip())\n    if found is None:\n        raise ValueError("expected integer quantity")\n    return int(found[1]) * {"": 1, "k": 1000, "M": 1000000}[found[2]]',
     'assert parse_quantity(" -2k ") == -2000\nassert parse_quantity("+7M") == 7000000\ntry:\n    parse_quantity("2 M")\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("accepted embedded whitespace")'),
    ("averaging", "Fix moving_mean(values, width) so it returns one mean per complete, contiguous window of width items. Consume values once in order. Return [] when the input is shorter than width and raise ValueError when width is less than 1.",
     'from collections import deque\n\ndef moving_mean(values, width):\n    if width < 1:\n        raise ValueError("width must be positive")\n    window = deque()\n    running = 0\n    result = []\n    for value in values:\n        window.append(value)\n        running += value\n        if len(window) == width:\n            result.append(running / width)\n            running -= window.popleft()\n    return result',
     'assert moving_mean(iter([1, 2, 6, 8]), 2) == [1.5, 4, 7]\nassert moving_mean(iter([2]), 3) == []'),
    ("unit_conversion", "Implement temperature_celsius(value, unit) supporting C, F, and K. Normalize the unit by stripping it and uppercasing. Raise ValueError for unknown units or temperatures strictly below absolute zero.",
     'def temperature_celsius(value, unit):\n    unit = unit.strip().upper()\n    if unit == "C":\n        threshold, result = -273.15, value\n    elif unit == "F":\n        threshold, result = -459.67, (value - 32) / 1.8\n    elif unit == "K":\n        threshold, result = 0, value - 273.15\n    else:\n        raise ValueError("unknown temperature unit")\n    if value < threshold:\n        raise ValueError("temperature below absolute zero")\n    return result',
     'assert temperature_celsius(212, " f ") == 100\nassert temperature_celsius(0, "K") == -273.15\ntry:\n    temperature_celsius(-300, "C")\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("temperature accepted")'),
    ("duration_parts", "Implement format_uptime(seconds) converting a nonnegative integer to DD:HH:MM:SS, padding each field to at least two digits. Day counts may exceed 99. Raise ValueError for negative input.",
     'def format_uptime(seconds):\n    if seconds < 0:\n        raise ValueError("negative uptime")\n    days, remainder = divmod(seconds, 86400)\n    hours, remainder = divmod(remainder, 3600)\n    minutes, seconds = divmod(remainder, 60)\n    return f"{days:02d}:{hours:02d}:{minutes:02d}:{seconds:02d}"',
     'assert format_uptime(90061) == "01:01:01:01"\nassert format_uptime(100 * 86400) == "100:00:00:00"\nassert format_uptime(0) == "00:00:00:00"'),
    ("index_valid", "Implement load_by_id(rows) returning a dict mapping each row's integer id to that row object. Reject duplicate ids and boolean ids with ValueError. Inputs are iterable mappings and might be streamed.",
     'def load_by_id(rows):\n    index = {}\n    for row in rows:\n        identifier = row.get("id")\n        if type(identifier) is not int or identifier in index:\n            raise ValueError("expected unique integer id")\n        index[identifier] = row\n    return index',
     'entry = {"id": 3, "status":"new"}\nassert load_by_id(iter([entry]))[3] is entry\nfor group in [[{"id":True}], [{"id":2},{"id":2}], [{}]]:\n    try:\n        load_by_id(group)\n    except ValueError:\n        continue\n    raise AssertionError(group)'),
    ("split_extension", "Implement split_backup(filename) splitting off the case-sensitive final extension .bak or .old if the stem is nonempty. Return (filename, None) for other names, including .bak itself.",
     'def split_backup(filename):\n    stem, separator, extension = filename.rpartition(".")\n    if stem and separator and extension in {"bak", "old"}:\n        return stem, separator + extension\n    return filename, None',
     'assert split_backup("db.1.bak") == ("db.1",".bak")\nassert split_backup(".bak") == (".bak", None)\nassert split_backup("db.OLD") == ("db.OLD", None)'),
    ("rolling_checksum", "Implement in_memory_digest(chunks) over any iterable of bytes. Return SHA-256 hexadecimal digest of their concatenation without joining the chunks, so iterators and large inputs work.",
     'import hashlib\n\ndef in_memory_digest(chunks):\n    digest = hashlib.sha256()\n    for chunk in chunks:\n        digest.update(chunk)\n    return digest.hexdigest()',
     'import hashlib\nassert in_memory_digest(iter([b"a", b"", b"be"])) == hashlib.sha256(b"abe").hexdigest()\nassert in_memory_digest(()) == hashlib.sha256().hexdigest()'),
    ("class_copy", "Implement class UsageCounter with record(amount=1) returning the new count, value property, and reset() returning the previous count and setting it to zero. Counts must be independent between instances and amounts cannot be negative.",
     'class UsageCounter:\n    def __init__(self):\n        self._count = 0\n\n    @property\n    def value(self):\n        return self._count\n\n    def record(self, amount=1):\n        if amount < 0:\n            raise ValueError("negative amount")\n        self._count += amount\n        return self._count\n\n    def reset(self):\n        previous = self._count\n        self._count = 0\n        return previous',
     'one, two = UsageCounter(), UsageCounter()\nassert one.record() == 1 and one.record(2) == 3\nassert two.value == 0 and one.reset() == 3 and one.value == 0'),
    ("drop_columns", "Implement project_columns(table, columns), yielding tuples containing the specified indices from each input row. columns can be a generator and can contain duplicates or negative indices. Propagate IndexError from undersized rows.",
     'def project_columns(table, columns):\n    indices = tuple(columns)\n    for row in table:\n        yield tuple(row[index] for index in indices)',
     'data = iter([[9, 5, 1], [8, 4, 2]])\nassert list(project_columns(data, iter([0, -1, 0]))) == [(9, 1, 9), (8, 2, 8)]\nassert list(project_columns([[2]], [])) == [()]'),
    ("priority_insertion", "Implement order_items(items, priorities), sorting items by the order of categories in priorities. An item is (category, display_name). Unknown categories go last. Preserve input order within each priority and among unknown categories.",
     'def order_items(items, priorities):\n    ranks = {}\n    for index, category in enumerate(priorities):\n        ranks.setdefault(category, index)\n    return sorted(items, key=lambda item: ranks.get(item[0], float("inf")))',
     'source = [("misc","x"), ("home","z"), ("misc2","y"), ("home","a"), ("work","b")]\nassert order_items(iter(source), ["work","home"]) == [source[i] for i in (4,1,3,0,2)]'),
    ("quadrant", "Implement quadrant(x, y) returning 1, 2, 3 or 4 for the open mathematical quadrants, counted counterclockwise starting in the positive-positive quadrant. Return None when either coordinate is zero.",
     'def quadrant(x, y):\n    if x == 0 or y == 0:\n        return None\n    if y > 0:\n        return 1 if x > 0 else 2\n    return 4 if x > 0 else 3',
     'assert [quadrant(*p) for p in [(1,1),(-1,1),(-1,-1),(1,-1),(0,2),(3,0)]] == [1,2,3,4,None,None]'),
    ("filesize_labels", "Implement filesize_label(size), accepting a nonnegative integer byte count. Format sizes below 1024 as e.g. '5 B'. Above that, choose the largest of KiB, MiB and GiB whose threshold is reached, and format with one decimal.",
     'def filesize_label(size):\n    if size < 0:\n        raise ValueError("negative size")\n    for power, label in ((3, "GiB"), (2, "MiB"), (1, "KiB")):\n        factor = 1024 ** power\n        if size >= factor:\n            return f"{size / factor:.1f} {label}"\n    return f"{size} B"',
     'assert filesize_label(1023) == "1023 B"\nassert filesize_label(1536) == "1.5 KiB"\nassert filesize_label(1024**3) == "1.0 GiB"'),
]

path = Path(__file__).with_name("supervised.jsonl")
path.write_text("".join(json.dumps(dict(id=i, prompt=p, solution=s, tests=t, license="CC0-1.0")) + "\n"
                        for i, p, s, t in examples))
